#include "cffex_disclosure_page.hpp"
#include "cffex_disclosure_model.hpp"
#include <QtWidgets>
#include <stdexcept>
namespace cffexDisclosure {
Page::Page(Host h,QString file,QWidget*parent):QWidget(parent),host(std::move(h)),store(file){
 auto*layout=new QVBoxLayout(this);auto*row=new QHBoxLayout;
 date=new QLineEdit(QDateTime::currentDateTimeUtc().toOffsetFromUtc(28800).date().toString(Qt::ISODate),this);date->setObjectName("cffexDate");date->setMaximumWidth(160);
 product=new QComboBox(this);product->addItems({"IF","IH","IC","IM"});product->setObjectName("cffexProduct");
 auto*fetch=new QPushButton("读取指定日期",this);fetch->setObjectName("cffexFetch");auto*stop=new QPushButton("取消读取",this);stop->setObjectName("cffexCancel");saveButton=new QPushButton("保存当前原文",this);saveButton->setObjectName("cffexSave");saveButton->setEnabled(false);rawButton=new QPushButton("查看原文与来源",this);rawButton->setObjectName("cffexOriginal");
 row->addWidget(new QLabel("披露日期",this));row->addWidget(date);row->addWidget(product);row->addWidget(fetch);row->addWidget(stop);row->addWidget(saveButton);row->addWidget(rawButton);row->addStretch();layout->addLayout(row);
 auto*selectors=new QHBoxLayout;history=new QComboBox(this);history->setObjectName("cffexHistory");contract=new QComboBox(this);contract->setObjectName("cffexContract");selectors->addWidget(history,2);selectors->addWidget(contract,1);layout->addLayout(selectors);
 summary=new QLabel("选择日期与品种，查看日终会员持仓排名。",this);summary->setTextFormat(Qt::PlainText);summary->setWordWrap(true);layout->addWidget(summary);
 stack=new QStackedWidget(this);layout->addWidget(stack,1);table=new QTableWidget(this);table->setObjectName("cffexRows");table->setColumnCount(5);table->setHorizontalHeaderLabels({"披露类别","排名","会员","持仓 / 成交（手）","较前次增减（手）"});table->setEditTriggers(QAbstractItemView::NoEditTriggers);table->setSelectionBehavior(QAbstractItemView::SelectRows);table->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);table->horizontalHeader()->setSectionResizeMode(2,QHeaderView::Stretch);table->verticalHeader()->hide();stack->addWidget(table);
 evidence=new QTextEdit(this);evidence->setObjectName("cffexEvidence");evidence->setReadOnly(true);stack->addWidget(evidence);status=new QLabel(this);status->setObjectName("cffexStatus");status->setTextFormat(Qt::PlainText);status->setWordWrap(true);layout->addWidget(status);
 fetch->setEnabled(bool(host.fetch));connect(fetch,&QPushButton::clicked,this,[this]{try{begin(date->text(),product->currentText());}catch(const std::exception&e){notice(QString::fromUtf8(e.what()));}});
 connect(stop,&QPushButton::clicked,this,[this]{cancel();notice("已取消读取，旧历史保留。");});connect(saveButton,&QPushButton::clicked,this,[this]{save();});connect(rawButton,&QPushButton::clicked,this,[this]{if(!back())openOriginal();});connect(history,&QComboBox::activated,this,[this](int i){selectHistory(i);});connect(contract,&QComboBox::currentIndexChanged,this,[this]{render();});reload();
}
Page::~Page(){cancel();}
void Page::notice(const QString&t){status->setText(t);}
void Page::reload(){archive=store.read();QSignalBlocker block(history);history->clear();history->addItem("选择已保存历史（只读）");for(auto v:archive["frames"].toArray()){auto r=QJsonDocument::fromJson(v.toObject()["json"].toString().toUtf8()).object(),q=r["request"].toObject();history->addItem(q["date"].toString()+" / "+q["product"].toString()+" / 接收 "+r["checkedAt"].toString());}}
QString Page::begin(const QString&day,const QString&p){auto q=request(day,p);if(!host.fetch)throw std::runtime_error("尚未接入读取来源");cancel();pending=q;active=QUuid::createUuid().toString(QUuid::WithoutBraces);auto token=active;notice("读取 "+day+" / "+p+"；最多15秒，不重试。");try{host.fetch(token,q);}catch(const std::exception&e){fail(token,QString::fromUtf8(e.what()));throw;}return token;}
bool Page::accept(const QString&t,const QJsonObject&r){if(t!=active||active.isEmpty())return false;try{auto safe=validate(r);if(safe["request"].toObject()!=pending)throw std::runtime_error("响应不属于指定日期和品种");active.clear();pending={};current=safe;show(current);saveButton->setEnabled(true);back();notice("读取成功 · 尚未保存；仅已披露排名席位。");return true;}catch(const std::exception&e){fail(t,QString::fromUtf8(e.what()));return false;}}
void Page::fail(const QString&t,const QString&why){if(t!=active||active.isEmpty())return;active.clear();pending={};notice("读取失败："+why+"；旧历史保留。");}
void Page::cancel(){auto token=active;active.clear();pending={};if(!token.isEmpty()&&host.cancel)host.cancel(token);}
bool Page::save(){if(current.isEmpty()||!saveButton->isEnabled())return false;try{store.save(current,qint64(archive["revision"].toDouble()));reload();saveButton->setEnabled(false);notice("原文已保存；独立历史档案，未修改旧业务库。");return true;}catch(const std::exception&e){notice(QString::fromUtf8(e.what()));return false;}}
bool Page::selectHistory(int index){try{auto frames=archive["frames"].toArray();if(index<1||index>frames.size())return false;cancel();current=validate(QJsonDocument::fromJson(frames[index-1].toObject()["json"].toString().toUtf8()).object());show(current);saveButton->setEnabled(false);back();notice("历史只读 · 接收于 "+current["checkedAt"].toString());return true;}catch(const std::exception&e){notice(QString::fromUtf8(e.what()));return false;}}
void Page::show(const QJsonObject&r){QSignalBlocker block(contract);contract->clear();for(auto v:r["contracts"].toArray())contract->addItem(v.toObject()["contract"].toString()+" / "+r["request"].toObject()["date"].toString());evidence->setPlainText("来源："+r["sourceUrl"].toString()+"\n接收："+r["checkedAt"].toString()+"\n原文 SHA256："+r["rawSha256"].toString()+"\n来源标记："+r["origin"].toString()+"\n交易日历及实际合约挂牌未独立核验。\n\n"+r["rawXml"].toString());render();}
void Page::render(){if(current.isEmpty())return;auto cs=current["contracts"].toArray();int index=contract->currentIndex();if(index<0||index>=cs.size())return;auto c=cs[index].toObject();auto number=[](QJsonValue v){return v.isNull()?QString("未知"):QString::number(v.toDouble(),'f',0);};
 summary->setText(c["contract"].toString()+" / "+c["tradingDay"].toString()+"   披露多头 "+number(c["listedLong"])+"   披露空头 "+number(c["listedShort"])+"   席位差额 "+number(c["listedDifference"])+" 手\n仅已列席位，不是全市场净流入；缺项为未知。  来源 "+(current["origin"]=="host-fetch-response"?"CFFEX响应（未独立核验）":"构造/导入材料，非实盘")+" · "+current["checkedAt"].toString());
 auto rows=c["rows"].toArray();table->setRowCount(rows.size());for(int i=0;i<rows.size();i++){auto r=rows[i].toObject();QStringList fields={r["type"]=="long"?"多头":r["type"]=="short"?"空头":"成交",number(r["rank"]),r["member"].toString(),number(r["volume"]),number(r["change"])};for(int j=0;j<fields.size();j++){auto*item=new QTableWidgetItem(fields[j]);if(j==1||j>2)item->setTextAlignment(Qt::AlignRight|Qt::AlignVCenter);table->setItem(i,j,item);}}
}
void Page::openOriginal(){if(current.isEmpty())return;stack->setCurrentIndex(1);rawButton->setText("返回披露榜");}
bool Page::back(){if(stack->currentIndex()!=1)return false;stack->setCurrentIndex(0);rawButton->setText("查看原文与来源");return true;}
QJsonObject Page::saveState()const{return{{"schema","cffex-reading/v1"},{"date",date->text()},{"product",product->currentText()},{"contract",contract->currentIndex()},{"original",stack->currentIndex()==1},{"scroll",evidence->verticalScrollBar()->value()},{"unsaved",saveButton->isEnabled()},{"report",current},{"status",status->text()}};}
void Page::restoreState(const QJsonObject&s){if(s["schema"]!="cffex-reading/v1")throw std::runtime_error("不是本页阅读状态");cancel();date->setText(s["date"].toString());product->setCurrentText(s["product"].toString());auto r=s["report"].toObject();if(!r.isEmpty()){current=validate(r);show(current);contract->setCurrentIndex(qBound(0,s["contract"].toInt(),contract->count()-1));saveButton->setEnabled(s["unsaved"].toBool());if(s["original"].toBool())openOriginal();else back();evidence->verticalScrollBar()->setValue(s["scroll"].toInt());}notice(s["status"].toString()+"（恢复阅读；未恢复在途请求）");}
}
